package com.gui.jhand.evaluator;

import lombok.NoArgsConstructor;

import java.util.Base64;

import static lombok.AccessLevel.PRIVATE;

/**
 * The HandEvaluatorTables class is responsible for storing lookup tables and utility
 * methods used during poker hand evaluation. These tables are precomputed to optimize the
 * evaluation process for specific hand characteristics such as flushes and unique card
 * combinations.
 */
@NoArgsConstructor(access = PRIVATE)
final class HandEvaluatorTables {

	static final short[] FLUSH_TABLE = decodeTable(
			"",
			8192);

	static final short[] FIVE_UNIQUE_CARDS_COMBINATIONS = decodeTable(
			"",
			8192);

	static final short[] HASH_ADJUST = decodeTable(
			"",
			512);

	static final short[] HASH_VALUES = decodeTable(
			"",
			8192);

	private static short[] decodeTable(String base64, int size) {
		byte[] bytes = Base64.getDecoder().decode(base64);
		short[] table = new short[size];
		for (int i = 0; i < size; i++) {
			table[i] = (short) ((bytes[i * 2] & 0xFF) | ((bytes[i * 2 + 1] & 0xFF) << 8));
		}
		return table;
	}

}
